pub mod cache;pub mod pixels;
fn main(){let args:Vec<_>=std::env::args().collect();let n:usize=args[1].parse().unwrap();let mut c=cache::FingerprintCache::default();for i in 0..n{let mut content=[0;32];content[..8].copy_from_slice(&(i as u64).to_le_bytes());c.insert(cache::CacheKey{content,recipe:[2;32],frame_index:3},pixels::Fingerprint{variants:[[123;4];8],mean_linear_rgb:[0.1,0.2,0.3],luminance_stddev:0.4},n).unwrap();}let mut bytes=Vec::new();c.write(&mut bytes,||false).unwrap();let checksum=blake3::hash(&bytes);let calls=std::cell::Cell::new(0u64);let start=std::time::Instant::now();for _ in 0..(100000/n.max(1)){let mut output=std::io::sink();c.write(&mut output,||{calls.set(calls.get()+1);std::hint::black_box(false)}).unwrap();}println!("{} {} {} {}",start.elapsed().as_nanos(),calls.get(),bytes.len(),checksum);}
